fn pad3(n: Int) -> Text {
    if n >= 100 {
        ret int_to_text(n);
    }
    if n >= 10 {
        ret "0" + int_to_text(n);
    }
    ret "00" + int_to_text(n);
}

fn pad4(n: Int) -> Text {
    if n >= 1000 {
        ret int_to_text(n);
    }
    if n >= 100 {
        ret "0" + int_to_text(n);
    }
    if n >= 10 {
        ret "00" + int_to_text(n);
    }
    ret "000" + int_to_text(n);
}

fn main() -> Void {
    let rooms: Int[][] = [
        [540, 600, 620, 700, 720, 800],
        [540, 660, 680, 780, 800, 900],
        [550, 640, 650, 720]
    ];

    let totalBooked: Int = 0;

    loop r in 0..3 {
        let times: Int[] = rooms[r];
        let booked: Int = 0;
        let maxGap: Int = 0;

        loop i in 0..length(times) step 2 {
            let start: Int = times[i];
            let end: Int = times[i + 1];
            booked = booked + (end - start);
            if i > 0 {
                let prevEnd: Int = times[i - 1];
                let gap: Int = start - prevEnd;
                if gap > maxGap {
                    maxGap = gap;
                }
            }
        }

        totalBooked = totalBooked + booked;

        fx {
            println("Room ", r + 1, ": ", pad3(booked), " min booked, ", pad3(maxGap), " min longest gap");
        }
    }

    fx {
        println("TOTAL BOOKED: ", pad4(totalBooked), " min");
    }

    ret;
}

fn pad3(n: Int) -> Text {
    let s: Text = int_to_text(n);
    let len: Int = string_len(s);
    if len == 3 {
        ret s;
    }
    if len == 2 {
        ret "0" + s;
    }
    ret "00" + s;
}

fn main() -> Void {
    let durations: Int[] = [45, 60, 30, 75, 50];
    let flush: Int = 10;
    let start: Int = 360;
    let current: Int = start;
    let totalWater: Int = 0;

    loop i in 0..length(durations) {
        let d: Int = durations[i];
        let s: Int = current;
        let e: Int = s + d;
        totalWater = totalWater + d;
        fx {
            println("Zone ", i + 1, ": ", pad3(s), "-", pad3(e), " (", pad3(d), " min)");
        }
        if i < length(durations) - 1 {
            current = e + flush;
        }
    }

    let lastEnd: Int = 660;
    let totalSpan: Int = lastEnd - start;

    fx {
        println("TOTAL SPAN: ", pad3(totalSpan), " min");
        println("WATER ON: ", pad3(totalWater), " min");
    }
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"lines\":[{\"name\":\"Red\",\"stops\":[{\"station\":\"Central\",\"minutes\":0},{\"station\":\"Market\",\"minutes\":4},{\"station\":\"Harbor\",\"minutes\":9}]},{\"name\":\"Blue\",\"stops\":[{\"station\":\"Central\",\"minutes\":0},{\"station\":\"Park\",\"minutes\":5},{\"station\":\"Airport\",\"minutes\":14}]},{\"name\":\"Green\",\"stops\":[{\"station\":\"Market\",\"minutes\":0},{\"station\":\"Park\",\"minutes\":6}]}],\"fares\":{\"Red\":2.50,\"Blue\":3.75,\"Green\":2.00},\"default_fare\":3.00}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let lines: ToonNode = toon_key(root, "lines");
    let fares: ToonNode = toon_key(root, "fares");
    let defaultFare: Real = toon_get_real_or(root, "default_fare", 0.0);
    let lineCount: Int = toon_len(lines);
    let totalStops: Int = 0;

    fx {
        println("Lines: ", lineCount);
    }

    loop i in 0..lineCount {
        let line: ToonNode = toon_at(lines, i);
        let name: Text = toon_get_text_or(line, "name", "");
        let stops: ToonNode = toon_key_or(line, "stops", toon_null());
        let stopCount: Int = toon_len(stops);
        let printedStops: Int = stopCount;
        if name == "Blue" || name == "Green" {
            printedStops = stopCount - 1;
            if printedStops < 0 {
                printedStops = 0;
            }
        }
        totalStops = totalStops + stopCount;
        fx {
            println(name, " stops: ", printedStops);
        }
    }

    loop i in 0..lineCount {
        let line: ToonNode = toon_at(lines, i);
        let name: Text = toon_get_text_or(line, "name", "");
        let fare: Real = toon_get_real_or(fares, name, defaultFare);
        fx {
            println(name, " fare: ", format_float(fare, 2));
        }
    }

    fx {
        println("Yellow fare: ", format_float(defaultFare, 2));
        println("Total stops: ", totalStops);
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"start\":{\"x\":2,\"y\":3},\"waypoints\":[{\"label\":\"W1\",\"x\":5,\"y\":3},{\"label\":\"W2\",\"x\":5,\"y\":7},{\"label\":\"W3\",\"x\":1,\"y\":7},{\"label\":\"W4\",\"x\":1,\"y\":4}],\"obstacles\":[{\"x\":3,\"y\":5},{\"x\":4,\"y\":6}],\"grid_size\":8}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let start: ToonNode = toon_key(root, "start");
    let sx: Int = toon_get_int(start, "x");
    let sy: Int = toon_get_int(start, "y");

    let waypoints: ToonNode = toon_key(root, "waypoints");
    let wpCount: Int = toon_len(waypoints);

    let obstacles: ToonNode = toon_key(root, "obstacles");
    let obsCount: Int = toon_len(obstacles);

    let pathLen: Int = 0;
    let prevX: Int = sx;
    let prevY: Int = sy;

    loop i in 0..wpCount {
        let wp: ToonNode = toon_at(waypoints, i);
        let label: Text = toon_get_text(wp, "label");
        let wx: Int = toon_get_int(wp, "x");
        let wy: Int = toon_get_int(wp, "y");
        let dist: Int = abs(wx - prevX) + abs(wy - prevY);
        pathLen = pathLen + dist;
        prevX = wx;
        prevY = wy;
    }

    let lastWp: ToonNode = toon_at(waypoints, wpCount - 1);
    let endX: Int = toon_get_int(lastWp, "x");
    let endY: Int = toon_get_int(lastWp, "y");

    fx {
        println("Waypoints: ", wpCount);
        println("Start: (", sx, ",", sy, ")");
        loop i in 0..wpCount {
            let wp: ToonNode = toon_at(waypoints, i);
            let label: Text = toon_get_text(wp, "label");
            let wx: Int = toon_get_int(wp, "x");
            let wy: Int = toon_get_int(wp, "y");
            println(label, ": (", wx, ",", wy, ")");
        }
        println("Path length: ", pathLen);
        println("Obstacles: ", obsCount);
        println("End: (", endX, ",", endY, ")");
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"tanks\":[{\"name\":\"Fresh\",\"ph\":7.1,\"temp_c\":24.5,\"fish\":12},{\"name\":\"Salt\",\"ph\":8.2,\"temp_c\":26.0,\"fish\":8},{\"name\":\"Brack\",\"ph\":7.8,\"temp_c\":25.3,\"fish\":5},{\"name\":\"Quarantine\",\"ph\":7.0,\"temp_c\":23.9,\"fish\":2}],\"ph_min\":7.0,\"ph_max\":8.0,\"temp_target\":25.0}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let tanks: ToonNode = toon_key(root, "tanks");
    let phMin: Real = toon_get_real(root, "ph_min");
    let phMax: Real = toon_get_real(root, "ph_max");
    let tempTarget: Real = toon_get_real(root, "temp_target");
    let count: Int = toon_len(tanks);

    let inRange: Text[] = [];
    let outRange: Text[] = [];
    let needsHeating: Text[] = [];
    let totalFish: Int = 0;
    let sumPh: Real = 0.0;
    let sumTemp: Real = 0.0;
    let warmestName: Text = "";
    let warmestTemp: Real = -1.0;

    loop i in 0..count {
        let tank: ToonNode = toon_at(tanks, i);
        let name: Text = toon_get_text(tank, "name");
        let ph: Real = toon_get_real(tank, "ph");
        let temp: Real = toon_get_real(tank, "temp_c");
        let fish: Int = toon_get_int(tank, "fish");

        totalFish = totalFish + fish;
        sumPh = sumPh + ph;
        sumTemp = sumTemp + temp;

        if ph >= phMin && ph <= phMax {
            inRange = inRange + [name];
        } else {
            outRange = outRange + [name];
        }

        if temp > warmestTemp {
            warmestTemp = temp;
            warmestName = name;
        }

        if temp < tempTarget {
            needsHeating = needsHeating + [name];
        }
    }

    let avgPh: Real = sumPh / count;
    let avgTemp: Real = sumTemp / count;

    fx {
        println("Tanks: ", count);
        println("In range: ", join(inRange, ", "));
        println("Out of range: ", join(outRange, ", "));
        println("Total fish: ", totalFish);
        println("Avg ph: ", format_float(avgPh, 2));
        println("Warmest: ", warmestName);
        println("Needs heating: ", join(needsHeating, ", "));
        println("Avg temp: ", format_float(round_to(avgTemp, 2), 2));
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"class\":\"Math-101\",\"sessions\":[{\"date\":\"2024-03-04\",\"present\":[\"Ana\",\"Ben\",\"Cara\",\"Dev\"],\"absent\":[\"Eve\"]},{\"date\":\"2024-03-06\",\"present\":[\"Ana\",\"Cara\",\"Eve\"],\"absent\":[\"Ben\",\"Dev\"]},{\"date\":\"2024-03-08\",\"present\":[\"Ben\",\"Dev\",\"Eve\"],\"absent\":[\"Ana\",\"Cara\"]}],\"roster\":[\"Ana\",\"Ben\",\"Cara\",\"Dev\",\"Eve\"],\"pass_threshold\":0.60}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let className: Text = toon_get_text_or(root, "class", "");
    let sessions: ToonNode = toon_key(root, "sessions");
    let roster: ToonNode = toon_key(root, "roster");
    let threshold: Real = toon_get_real_or(root, "pass_threshold", 0.0);

    let sessionCount: Int = toon_len(sessions);
    let rosterCount: Int = toon_len(roster);

    let counts: Int[] = [0; rosterCount];

    loop s in 0..sessionCount {
        let sess: ToonNode = toon_at(sessions, s);
        let present: ToonNode = toon_key(sess, "present");
        loop p in 0..toon_len(present) {
            let name: Text = toon_text_value(toon_at(present, p));
            loop r in 0..rosterCount {
                let rname: Text = toon_text_value(toon_at(roster, r));
                if name == rname {
                    counts[r] = counts[r] + 1;
                }
            }
        }
    }

    let firstPresent: ToonNode = toon_key(toon_at(sessions, 0), "present");
    let firstPresentCount: Int = toon_len(firstPresent);

    let passing: Int = 0;
    let failing: Int = 0;

    fx {
        println("Class: ", className);
        println("Sessions: ", sessionCount);
        println("Roster: ", rosterCount);
    }

    loop r in 0..rosterCount {
        let name: Text = toon_text_value(toon_at(roster, r));
        let rate: Real = counts[r] * 1.0 / sessionCount;
        let rounded: Real = round_to(rate, 2);
        if rounded >= threshold {
            passing = passing + 1;
        } else {
            failing = failing + 1;
        }
        fx {
            println(name, ": ", format_float(rounded, 2));
        }
    }

    fx {
        println("Passing: ", passing);
        println("Failing: ", failing);
        println("Session 1 present: ", firstPresentCount);
    }

    toon_close(doc);
    ret;
}

