fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"plots\":[{\"plot\":\"P1\",\"readings\":{\"moisture\":45,\"ph\":6.5,\"fertilized\":true}},{\"plot\":\"P2\",\"readings\":{\"moisture\":30,\"ph\":7.2,\"fertilized\":false}},{\"plot\":\"P3\",\"readings\":{\"moisture\":55,\"ph\":6.8,\"fertilized\":true}}]}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let plots: ToonNode = toon_key(root, "plots");
    let fertilizedCount: Int = 0;

    loop i in 0..toon_len(plots) {
        let plot: ToonNode = toon_at(plots, i);
        let plotName: Text = toon_get_text_or(plot, "plot", "?");
        let readings: ToonNode = toon_key_or(plot, "readings", toon_null());

        let moistureType: Text = "Unknown";
        if toon_has_key(readings, "moisture") {
            let mNode: ToonNode = toon_key(readings, "moisture");
            if toon_is_int(mNode) {
                moistureType = "Int";
            } else if toon_is_real(mNode) {
                moistureType = "Real";
            } else if toon_is_bool(mNode) {
                moistureType = "Bool";
            }
        }

        let phType: Text = "Unknown";
        if toon_has_key(readings, "ph") {
            let pNode: ToonNode = toon_key(readings, "ph");
            if toon_is_int(pNode) {
                phType = "Int";
            } else if toon_is_real(pNode) {
                phType = "Real";
            } else if toon_is_bool(pNode) {
                phType = "Bool";
            }
        }

        let fertilizedType: Text = "Unknown";
        let isFertilized: Bool = false;
        if toon_has_key(readings, "fertilized") {
            let fNode: ToonNode = toon_key(readings, "fertilized");
            if toon_is_int(fNode) {
                fertilizedType = "Int";
            } else if toon_is_real(fNode) {
                fertilizedType = "Real";
            } else if toon_is_bool(fNode) {
                fertilizedType = "Bool";
                isFertilized = toon_bool_value(fNode);
            }
        }

        if isFertilized {
            fertilizedCount = fertilizedCount + 1;
        }

        fx {
            println(plotName, ": moisture=", moistureType, ", ph=", phType, ", fertilized=", fertilizedType);
        }
    }

    fx {
        println("Fertilized plots: ", fertilizedCount);
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
