fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"class\":\"Math101\",\"students\":[{\"name\":\"Ana\",\"scores\":[88,92,79]},{\"name\":\"Ben\",\"scores\":[65,71,68]},{\"name\":\"Cleo\",\"scores\":[95,91,97]},{\"name\":\"Dev\",\"scores\":[72,66,70]}],\"passMark\":70}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let className: Text = toon_get_text_or(root, "class", "");
    let passMark: Int = toon_get_int_or(root, "passMark", 0);
    let students: ToonNode = toon_key(root, "students");
    let count: Int = toon_len(students);

    fx {
        println("Class: ", className);
        println("Students: ", count);
    }

    let passing: Int = 0;
    let topName: Text = "";
    let topAvg: Real = -1.0;

    loop i in 0..count {
        let student: ToonNode = toon_at(students, i);
        let name: Text = toon_get_text_or(student, "name", "");
        let scores: ToonNode = toon_key(student, "scores");
        let sCount: Int = toon_len(scores);
        let total: Int = 0;
        loop j in 0..sCount {
            let s: ToonNode = toon_at(scores, j);
            total = total + toon_int_value(s);
        }
        let avg: Real = 0.0;
        if sCount > 0 {
            avg = total * 1.0 / sCount;
        }
        let avgRounded: Real = round_to(avg, 1);
        if avgRounded >= passMark {
            passing = passing + 1;
        }
        if avgRounded > topAvg {
            topAvg = avgRounded;
            topName = name;
        }
        fx {
            println(name, ": ", format_float(avgRounded, 1));
        }
    }

    fx {
        println("Passing: ", passing);
        println("Top: ", topName);
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("warehouse.json"); }
    let root: ToonNode = toon_root(doc);

    let n: Int = toon_len(root);
    let zoneA: Int = 0;
    let zoneB: Int = 0;
    let zoneC: Int = 0;
    let topId: Text = "";
    let topFree: Int = -1;
    let p1Count: Int = 0;

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let id: Text = toon_get_text_or(row, "id", "");
        let zone: Text = toon_get_text_or(row, "zone", "");
        let capacity: Int = toon_get_int_or(row, "capacity", 0);
        let used: Int = toon_get_int_or(row, "used", 0);
        let priority: Int = toon_get_int_or(row, "priority", 3);
        let free: Int = capacity - used;

        if zone == "A" {
            zoneA = zoneA + free;
        }
        if zone == "B" {
            zoneB = zoneB + free;
        }
        if zone == "C" {
            zoneC = zoneC + free;
        }

        if free > topFree || (free == topFree && id < topId) {
            topFree = free;
            topId = id;
        }

        if priority == 1 {
            p1Count = p1Count + 1;
        }
    }

    fx {
        println("Zone A free: ", zoneA);
        println("Zone B free: ", zoneB);
        println("Zone C free: ", zoneC);
        println("Top shelf: ", topId, " with ", topFree, " free");
        println("Priority 1 count: ", p1Count);
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("nursery.json"); }
    let root: ToonNode = toon_root(doc);

    let n: Int = toon_len(root);
    let names: Text[] = [];
    let stocks: Int[] = [];
    let reorderAts: Int[] = [];
    let suns: Int[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let name: Text = toon_get_text_or(row, "name", "");
        let stock: Int = toon_get_int_or(row, "stock", 0);
        let reorderAt: Int = toon_get_int_or(row, "reorderAt", 0);
        let sun: Int = toon_get_int_or(row, "sunlight", 6);
        names = names + [name];
        stocks = stocks + [stock];
        reorderAts = reorderAts + [reorderAt];
        suns = suns + [sun];
    }

    let reorderIdx: Int[] = [];
    loop i in 0..n {
        if stocks[i] <= reorderAts[i] {
            reorderIdx = reorderIdx + [i];
        }
    }

    let sortedIdx: Int[] = [];
    loop i in 0..length(reorderIdx) {
        let best: Int = -1;
        loop j in 0..length(reorderIdx) {
            if best == -1 {
                best = j;
            } else {
                let a: Int = reorderIdx[best];
                let b: Int = reorderIdx[j];
                if names[b] < names[a] {
                    best = j;
                }
            }
        }
        sortedIdx = sortedIdx + [reorderIdx[best]];
        let rest: Int[] = [];
        loop j in 0..length(reorderIdx) {
            if j != best {
                rest = rest + [reorderIdx[j]];
            }
        }
        reorderIdx = rest;
    }

    fx {
        if length(sortedIdx) == 0 {
            println("No reorders needed");
        } else {
            loop k in 0..length(sortedIdx) {
                let i: Int = sortedIdx[k];
                println(names[i], " (", stocks[i], "/", reorderAts[i], ")");
            }
        }

        let total: Int = 0;
        loop i in 0..n {
            total = total + stocks[i];
        }
        println("Total stock: ", total);

        let topIdx: Int = 0;
        loop i in 1..n {
            if suns[i] > suns[topIdx] {
                topIdx = i;
            } else if suns[i] == suns[topIdx] {
                if names[i] < names[topIdx] {
                    topIdx = i;
                }
            }
        }
        println("Top sunlight: ", names[topIdx], " needs ", suns[topIdx], "h");

        let lowCount: Int = 0;
        loop i in 0..n {
            if suns[i] < 4 {
                lowCount = lowCount + 1;
            }
        }
        println("Low sunlight count: ", lowCount);
    }

    toon_close(doc);
    ret;
}

