fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc = toon_parse("{\"players\":[{\"name\":\"Ana\",\"score\":142,\"bonus\":3.5},{\"name\":\"Bo\",\"score\":98,\"bonus\":0.0},{\"name\":\"Cy\",\"score\":175,\"bonus\":7.25}]}");
    let root: ToonNode = toon_root(doc);
    let players: ToonNode = toon_key(root, "players");
    let n: Int = toon_len(players);

    let names: Text[] = [];
    let totals: Real[] = [];

    loop i in 0..n {
        let p: ToonNode = toon_at(players, i);
        let name: Text = toon_get_text_or(p, "name", "");
        let score: Int = toon_get_int_or(p, "score", 0);
        let bonus: Real = toon_get_real_or(p, "bonus", 0.0);
        names = names + [name];
        totals = totals + [score + bonus];
    }

    let order: Int[] = [];
    loop i in 0..n {
        order = order + [i];
    }

    loop i in 0..n {
        let maxIdx: Int = i;
        loop j in i + 1..n {
            if totals[order[j]] > totals[order[maxIdx]] {
                maxIdx = j;
            }
        }
        let tmp: Int = order[i];
        order[i] = order[maxIdx];
        order[maxIdx] = tmp;
    }

    fx {
        println("Rank  Name   Total");
        loop i in 0..n {
            let idx: Int = order[i];
            let rank: Int = i + 1;
            let name: Text = names[idx];
            let total: Real = totals[idx];
            let rankStr: Text = int_to_text(rank);
            let totalStr: Text = format_float(total, 2);
            let rankPad: Int = 4 - string_len(rankStr);
            let namePad: Int = 4 - string_len(name);
            let totalPad: Int = 6 - string_len(totalStr);
            let line: Text = rankStr;
            loop k in 0..rankPad {
                line = line + " ";
            }
            line = line + "  ";
            line = line + name;
            loop k in 0..namePad {
                line = line + " ";
            }
            line = line + "  ";
            loop k in 0..totalPad {
                line = line + " ";
            }
            line = line + totalStr;
            println(line);
        }
    }

    toon_close(doc);
    ret;
}

